import { ISessionManagementProgressTranslations, ISessionStatus } from '../../types';
import { Component, Inject, Prop, Vue, Watch } from 'vue-property-decorator';
import AcceptPopup from '../accept-popup/index.vue';

const LIMIT_APPROACHING_DISPLAY_TIME = 120;

@Component({
    components: { AcceptPopup }
})
export default class LimitApproaching extends Vue {
    @Prop()
    public readonly translations: ISessionManagementProgressTranslations;

    @Prop()
    public readonly sessionStatus: ISessionStatus;

    @Prop()
    public readonly sessionDuration: number;

    @Prop()
    public hasLowBalance: boolean;

    @Inject()
    public readonly stringifyTime: (seconds: number) => string;

    @Inject()
    public readonly stringifyBet: (bet: number) => string;

    public withinTimeThreshold: boolean = false;
    public closed: boolean = false;

    get visible(): boolean {
        return (!this.sessionStatus.SessionEnded && this.withinTimeThreshold && !this.closed);
    }

    get netBalance(): string {
        return this.stringifyBet(this.sessionStatus.NetBalance);
    }

    get timeSpent(): string {
        return this.stringifyTime(this.sessionDuration);
    }

    @Watch('sessionStatus', { immediate: true, deep: true })
    public onSessionStatusChanged(): void {
        if (this.sessionStatus.SessionEnded) {
            this.withinTimeThreshold = false;
            this.closed = false;
        }
    }

    @Watch('sessionDuration')
    public onSessionDurationChanged(): void {
        const timeLeftInSession = this.sessionStatus.MaxTime - this.sessionDuration;

        if (!this.sessionStatus.SessionEnded && timeLeftInSession > 0 && (timeLeftInSession <= LIMIT_APPROACHING_DISPLAY_TIME)) {
            this.withinTimeThreshold = true;
        }
    }

    @Watch('visible', { immediate: true })
    public onVisible(): void {
        if (this.visible) {
            this.$emit('alert');
        }
    }

    public onClose(): void {
        this.closed = true;
    }
}